const classes=Object.fromEntries(DATA.classes.map(c=>[c.id,{...c,...CLASS_RULES[c.id]}]));
let ROOMS=[];
const $=id=>document.getElementById(id),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let s=null,selected=null,uid=0,timer=null,speed=1,logs=[],stock=[],reward=[],toastTimer,catalogueState={search:'',group:'',classId:'',variant:'',mechanic:'',availability:'obtainable',page:0},catalogueOpen=false,returnModal=null,modalKind='',dragId=null;
function isOffClass(d,classId=s?.classId){return !!classId&&d.group!=='ring'&&d.group!=='consumable'&&Array.isArray(d.classes)&&d.classes.length>0&&d.classes.length<Object.keys(classes).length&&!d.classes.includes(classId)}
function itemManaCost(d,i=null){if(i)return enchantManaCost(d,i);return (d.mana||0)+(isOffClass(d)&&d.group==='ability'?1:0)}
function affinityCooldown(d){return d.cd*(isOffClass(d)?1.5:1)}
function affinityNote(d){const native=Array.isArray(d.classes)?d.classes:[];if(d.group==='ring'||d.group==='consumable'||!native.length||native.length===Object.keys(classes).length)return '';const names=native.map(id=>classes[id]?.name||id).join(', ');return `<div class="affinity-note ${isOffClass(d)?'offclass':''}"><b>${isOffClass(d)?'⚠ OFF-CLASS EQUIPMENT':'✓ CLASS COMPATIBLE'}</b><p>Native classes: ${esc(names)}.</p>${isOffClass(d)?`<p>Cooldown +50%: ${d.cd}s → ${itemTiming(d)}.${d.group==='ability'?` Mana +1: ${d.mana} → ${itemManaCost(d)}.`:''}</p>`:'<p>No off-class penalty.</p>'}</div>`}
function art(id,cls=''){const d=defs[id];return spriteMarkup(d.sprite,d.name,`itempixel ${cls} ${d.isShiny?'shiny-sprite':''}`)}
function dims(i){const d=defs[i.type];return i.rot?[d.h,d.w]:[d.w,d.h]}
function occupied(i){const [w,h]=dims(i);return Array.from({length:w*h},(_,n)=>[i.x+n%w,i.y+Math.floor(n/w)])}
function fits(i,x,y,rot=i.rot){if(!Number.isInteger(x)||!Number.isInteger(y))return false;const [w,h]=dims({...i,rot});return x>=0&&y>=0&&x+w<=6&&y+h<=5&&!s.items.some(j=>j.id!==i.id&&occupied(j).some(([a,b])=>a>=x&&a<x+w&&b>=y&&b<y+h))}
function adjacent(a,b){
 const ad=defs[a.type],bd=defs[b.type],aw=a.rot?ad.h:ad.w,ah=a.rot?ad.w:ad.h,bw=b.rot?bd.h:bd.w,bh=b.rot?bd.w:bd.h;
 const ax=a.x,ay=a.y,bx=b.x,by=b.y;
 // Keep legacy behavior for unplaced or overlapping fixtures; packed gear uses edge checks.
 if(!Number.isInteger(ax)||!Number.isInteger(ay)||!Number.isInteger(bx)||!Number.isInteger(by)||(ax<bx+bw&&bx<ax+aw&&ay<by+bh&&by<ay+ah))return occupied(a).some(([x,y])=>occupied(b).some(([u,v])=>Math.abs(x-u)+Math.abs(y-v)===1));
 return ((ax+aw===bx||bx+bw===ax)&&ay<by+bh&&by<ay+ah)||((ay+ah===by||by+bh===ay)&&ax<bx+bw&&bx<ax+aw)
}
function makeItem(type){return initEnchantPotential(initDaggerEnchantments({id:++uid,type,x:null,y:null,rot:false,charge:0,activations:0,used:false,quantity:consumableBundleSize(type),usesSpent:0}))}
function autoPlace(i){for(const rot of [false,true])for(let y=0;y<5;y++)for(let x=0;x<6;x++)if(fits(i,x,y,rot)){Object.assign(i,{x,y,rot});s.items.push(i);return true}return false}
function rng(){s.seed=(Math.imul(1664525,s.seed)+1013904223)>>>0;return s.seed/4294967296}
let journalTimer=0,journalDirty=false;
function flushJournal(){
 clearTimeout(journalTimer);journalTimer=0;if(window.__TEST__||!journalDirty)return;
 const node=$('log');if(!node||node.closest('[hidden]')||!node.getClientRects().length)return;
 node.innerHTML=logs.map(v=>`<div>${esc(v)}</div>`).join('');journalDirty=false
}
function log(t){logs.unshift(t);if(logs.length>70)logs.length=70;if(window.__TEST__)return;journalDirty=true;if(s?.phase==='fight'){if(!journalTimer)journalTimer=setTimeout(flushJournal,100)}else flushJournal()}

function toast(t){if(window.__TEST__)return;const notice=$('referenceNotification');if(notice){const original=notice.textContent;notice.textContent=t;notice.dataset.hasMessage='true';notice.title=t;$('toast').style.display='none';clearTimeout(toastTimer);toastTimer=setTimeout(()=>{if(notice.isConnected){notice.textContent=original;delete notice.dataset.hasMessage}},2900);return;}$('toast').textContent=t;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',2900)}
function flash(id){if(window.__TEST__||effectsQuality==='off'||document.hidden||modalKind||id.startsWith('item')&&!visualPackVisible())return;const e=$(id);if(!e)return;e.classList.add('flash');setTimeout(()=>e.classList.remove('flash'),160)}
function passive(event,amount){if(!amount||s.phase!=='fight')return;const c=classes[s.classId];if(c.event!==event)return;s.progress+=amount;let guard=0;while(s.progress>=c.threshold&&guard++<50){s.progress-=c.threshold;switch(c.proc){case'rogue':s.dodge=Math.min(3,s.dodge+1);hit(12);break;case'archer':s.precisionReady=true;break;case'wizard':s.arcaneEchoReady=true;break;case'priest':gainBlock(10);hit(14);break;case'warrior':s.fury=Math.min(5,(s.fury||0)+1);s.furyTime=10;break;case'knight':hit(18);gainBlock(4);break;case'paladin':restore(5,false);gainBlock(7);break;case'assassin':apply('poison',5);apply('vulnerable',3);break;case'necromancer':hit(14);restore(7,false);summon(3,10);break;case'huntress':apply('bleed',5);apply('weaken',4);break;case'mystic':delayEnemyAttack(1.5);hit(15);break;case'trickster':s.dodge=Math.min(3,s.dodge+1);summon(3,8);break;case'sorcerer':hit(20);apply('vulnerable',4);break;case'ninja':hit(16);s.mana=Math.min(manaCapacity(),s.mana+2);break;case'samurai':s.focus=Math.min(3,(s.focus||0)+1);break;case'bard':s.mana=Math.min(manaCapacity(),s.mana+2);gainBlock(6);break;case'summoner':summon(5,10);gainBlock(6);break;case'kensei':hit(16);gainBlock(6);break;case'druid':summon(4,10);gainBlock(6);break}log('✦ '+c.title+' activates.');flash('playerSprite')}}
function summon(power,duration,source=null){if(s.summons.length<8)s.summons.push({power,duration,ownerId:source?.id});else s.summons[0].duration=Math.max(s.summons[0].duration,duration)}
function apply(effect,amount,source=null){const e=s.enemy;switch(effect){case'damage':return hit(amount+s.power);case'drain':{const dealt=hit(amount+s.power);restore(Math.ceil(dealt*.4),true,source);return dealt}case'heal':return restore(amount,true,source);case'block':gainBlock(amount,source);break;case'mana':gainMana(amount,source);break;case'burn':e.burn=Math.min(80,e.burn+amount);break;case'poison':e.poison=Math.min(24,e.poison+amount);e.poisonTime=10;break;case'bleed':e.bleed=Math.min(24,e.bleed+amount);e.bleedTime=6;break;case'chill':case'weaken':case'vulnerable':e[effect]=Math.min(15,e[effect]+amount);break;case'haste':grantItemHaste(source,amount);break;case'summon':summon(amount,8,source);break;case'thorns':s.thorns=Math.min(35,s.thorns+amount);break;case'dodge':s.dodge=Math.min(3,s.dodge+amount);break;case'charge':s.power=Math.min(40,s.power+amount);break}}
function effectText(effect,n){return ({damage:`Deal ${n} damage`,drain:`Deal ${n} damage and heal for 40% dealt`,heal:`Restore ${n} health`,block:`Gain ${n} block`,mana:`Generate ${n} mana`,burn:`Apply ${n} burning (ticks each second; decays)`,poison:`Apply ${n} poison (ticks for 10s; decays 1 stack/s; max 24)`,bleed:`Apply ${n} bleed (ticks for 6s; decays 1 stack/s; max 24)`,chill:`Chill for ${n}s (enemy attacks 35% slower)`,weaken:`Weaken for ${n}s (enemy deals 25% less damage)`,vulnerable:`Expose for ${n}s (enemy takes 25% more damage)`,haste:`Grant adjacent items ${Math.min(15,n)}s of haste (+25% recharge; shared edges only, excludes self; refreshes, does not stack)`,summon:`Summon a ${n}-damage companion for 8s (attacks each second)`,thorns:`Gain ${n} thorns (reflect on each enemy attack)`,dodge:`Gain ${n} dodge charge${n===1?'':'s'} (avoid an attack)`,charge:`Gain +${n} damage power for this battle`})[effect]||effect}
function describe(d){if(d.realmIdentity&&d.mechanic?.summary)return realmSummary(d);if(d.consumableRework)return consumableDescription(d);if(passiveRing(d))return ringDescription(d)+' Passive bonus; enchantments retain their activation cycle.';const bundle=consumableBundleSize(d.id)>1?' Contains '+consumableBundleSize(d.id)+' copies.':'';if(d.daggerUpdate&&d.mechanic.perShot)return `Fire ${d.mechanic.shots} shots for ${d.amount} base damage each (${d.amount*d.mechanic.shots} total before misses).`;if(d.mechanic?.regen)return `Restore ${d.amount} health over ${d.mechanic.regen}s. Strongest mushroom only; healing fatigue applies.`;if(d.mechanic)return `${effectText(d.effect,d.amount)}.${d.mechanic.keepAffix&&d.affix?' '+effectText(d.affix,d.affixAmount)+'.':''}${d.once?bundle+' Stackable to 5; one use per copy per battle.':''}${healingConsumableNote(d)}`;return `${effectText(d.effect,d.amount)}.${d.affix?' '+effectText(d.affix,d.affixAmount)+'.':''}${d.once?bundle+' Stackable to 5; one use per copy per battle.':''}${healingConsumableNote(d)}`}
function conditionActive(i){const d=defs[i.type],others=s.items.filter(j=>j.id!==i.id);switch(d.condition){case'adjacent weapon':return nearbyItems(i).some(j=>defs[j.type].group==='weapon');case'adjacent ability':return nearbyItems(i).some(j=>defs[j.type].group==='ability');case'adjacent ring':return nearbyItems(i).some(j=>defs[j.type].group==='ring');case'same-row ally':return others.some(j=>j.y===i.y);case'every third activation':return (i.activations+1)%3===0;case'below half health':return s.hp<s.max/2;case'above half mana':return s.mana>=10;case'while shielded':return s.block>0;case'while enemy afflicted':return s.enemy.burn+s.enemy.poison+s.enemy.bleed+s.enemy.chill+s.enemy.weaken+s.enemy.vulnerable>0;case'first activation':return i.activations===0;default:return false}}
function activate(i){if(consumableProfile(i)){const result=activateReworkedConsumable(i);if(result!==null)return result}if(passiveRing(defs[i.type])&&!ringCanActivate(i))return false;if(!healingConsumableReady(i))return false;const d=defs[i.type];if(d.mechanic)return activateSignature(i);let armorTargetBefore=s.enemy.hp+(s.enemy.ward||0);const manaCost=itemManaCost(d,i);if(manaCost>s.mana||i.used)return false;const boosted=conditionActive(i);s.mana-=manaCost;passive('mana',manaCost);i.activations++;i.charge=0;consumeStackUse(i);beforeEnchantments(i);armorTargetBefore=s.enemy.hp+(s.enemy.ward||0);const primary=classPrimaryAmount(i,enchantPrimary(i,consumablePrimary(i,d.amount),true));apply(d.effect,primary,i);if(d.affix)apply(d.affix,d.affixAmount,i);if(boosted){if(['damage','drain','block','heal'].includes(d.effect))apply(d.effect,d.bonus,i);else hit(d.bonus);log('✧ '+d.name+' synergy: +'+d.bonus+(['damage','drain','block','heal'].includes(d.effect)?' '+d.effect:' damage')+'.')}if(d.group==='weapon'&&s.enemy.hp+(s.enemy.ward||0)<armorTargetBefore)armorWeaponHit(i,i.activations);if(d.group==='weapon'){passive('attack',1);itemEvent('weapon',1,i)}else if(d.group==='ability')itemEvent('ability',1,i);triggerEnchantments(i);classActivation(i,primary);itemFxActivation(i,boosted);s.lastItemEffect={itemId:i.id,effect:d.effect,amount:primary};log(d.name+': '+(passiveRing(d)?'enchantments activate':effectText(d.effect,primary))+'.');flash('item'+i.id);return true}
function enterRest(){daggerNoncombatBonus();s.phase='rest';save();showRest()}
function enterShop(){return enterSpecialistShop()}
function buy(id){if(s.phase!=='shop'||!stock.includes(id))return;if(!daggerAvailable(id)||defs[id]?.lootExcluded)return toast('This item is currently unavailable.');const d=defs[id];if(s.gold<d.price)return toast('Not enough gold.');if(!receiveItem(makeItem(id)))return;s.gold-=d.price;stock=stock.filter(t=>t!==id);save();render();showShop()}
function buyHeal(){if(s.phase!=='shop')return;if((s.shopHeals||0)>=1)return toast('The trader has no healing draughts left.');if(s.gold<25)return toast('You need 25 gold.');if(s.hp>=s.max)return toast('Already at full health.');s.gold-=25;s.shopHeals=(s.shopHeals||0)+1;restore(25,false);save();render();showShop()}
function leaveShop(){if(s.phase==='shop')nextRoom()}
function primary(){if(['won','lost'].includes(s.phase))chooseClass();else if(s.phase==='prep')startFight();else restorePhaseModal()}
let inspected=null;
function findInspected(){return [...s.items,...s.stash].find(i=>i.id===inspected)||findSelected()}
function findSelected(){return [...s.items,...s.stash].find(i=>i.id===selected)}
function place(x,y){if(s.phase!=='prep')return toast('Rearrange your backpack between battles.');const i=findSelected();if(!i)return toast('Select an item first.');const merge=stackAtCell(i,x,y);if(merge&&mergeStacks(i,merge))return;if(!fits(i,x,y))return toast('That item does not fit. Try rotating it or clearing space.');s.stash=s.stash.filter(j=>j.id!==i.id);if(!s.items.includes(i))s.items.push(i);Object.assign(i,{x,y});render();save()}
function rotateSelected(){inventoryRotate()}
function stashSelected(){if(s.phase!=='prep')return;const i=findSelected();if(!i||!s.items.includes(i))return;if(!stashCanReceive(i,false))return toast(STASH_FULL_MESSAGE);s.items=s.items.filter(j=>j.id!==i.id);Object.assign(i,{x:null,y:null});receiveItem(i,false);render();save()}
function discardSelected(id=selected){if(s.phase==='prep'&&[...s.items,...s.stash].some(i=>i.id===id&&consumableProfile(i)?.mode==='chest'))return openStatChest(id);if(s.phase!=='prep')return;const i=[...s.items,...s.stash].find(i=>i.id===id);if(!i)return;modal('Discard '+defs[i.type].name+'?','This removes the entire selected stack or item from your current run.',`<button id="cancelDiscard" onclick="closeModal(true)">Keep item</button> <button class="gold" onclick="removeItem(${i.id})">Discard item</button>`,'confirm')}
function removeItem(id){if(s.phase!=='prep'||![...s.items,...s.stash].some(i=>i.id===id))return;if(inspected===id)inspected=null;if(effectHover===id)effectHover=null;inventoryCancel();s.items=s.items.filter(i=>i.id!==id);s.stash=s.stash.filter(i=>i.id!==id);selected=null;closeModal(true);render();save()}
function selectItem(id){const i=[...s.items,...s.stash].find(i=>i.id===id);if(!i)return;inspected=id;const deselect=selected===id;inventoryIntent=null;inventoryClearPreview();selected=deselect?null:id;if(!deselect&&s.phase==='prep')inventoryPick(i);render()}
function cycleSpeed(){speed=speed===1?2:speed===2?4:1;$('speed').textContent=speed+'×'}
function modal(title,desc,body,kind='normal'){if(window.__TEST__)return;if(typeof stopItemPulses==='function')stopItemPulses();modalKind=kind;$('overlay').innerHTML=`<div class="overlay"><div class="modal ${kind==='catalogue'?'catalogue-modal':kind==='classes'?'classes-modal':kind==='reward'?'reward-modal':kind==='rewardinspect'?'reward-inspect-modal':kind==='shop'?'shop-modal':kind==='shopinspect'?'shop-inspect-modal':kind==='trade'?'event-trade-modal':''}"><div class="eyebrow">REALMPACK · THE SHATTERED VAULT</div><h1>${title}</h1><p>${desc}</p>${body}</div></div>`}
function confirmRestart(){if(s?.phase==='fight')return toast('Finish the battle before changing characters.');modal('Start a new run?','Choose a character next. Your current run is only replaced when you press Start.',`<div class="restart-actions"><button id="cancelRestart" onclick="closeModal()">Keep playing</button><button class="gold" onclick="chooseClass()">Choose character →</button></div>`,'confirm')}
function itemCard(id,action){const d=defs[id];return `<button class="choice ${d.isShiny?'shiny':''}" onclick="${action}"><div class="ico">${art(id)}</div><b>${esc(d.name)}</b><small style="color:${d.color}">${d.rarity} · ${esc(d.tier)} · ${esc(d.kind)} · ${d.w}×${d.h}</small><p>${esc(describe(d))}</p>${shinyInfo(d)}${affinityNote(d)}${adjacencyGuide(d)}<small>◷ ${itemTiming(d)}${itemManaCost(d)?' · ✦ '+itemManaCost(d)+' mana':''}</small>${d.mechanic||d.realmSet?mechanicCard(d):d.bonus?`<p class="synergy">${esc(d.condition)}: +${d.bonus} ${['damage','drain','block','heal'].includes(d.effect)?d.effect:'damage'}</p>`:''}</button>`}
function rewardCard(id,context='reward'){const shop=context==='shop',inspect=shop?'inspectShop':'inspectReward',take=shop?'buy':'takeLoot',d=defs[id],off=isOffClass(d),room=stashCanReceive({id:-1,type:id}),primary=d.consumableRework?consumableOfferSummary(d):d.realmIdentity&&d.mechanic?.summary?realmSummary(d):(passiveRing(d)?ringDescription(d):effectText(d.effect,d.amount)).replace(/\s*\([^)]*\)/g,'');return `<article class="loot-card ${d.isShiny?'shiny':''}"><div class="loot-heading">${art(id)}<div><h2>${esc(d.name)}</h2><small style="color:${d.color}">${esc(d.rarity)} · ${esc(d.tier)} · ${esc(d.kind)}${d.isShiny?' · Shiny':''}</small></div></div><div class="loot-stats"><span>${d.w}×${d.h}</span><span>◷ ${itemTiming(d)}${itemManaCost(d)?' · ✦ '+itemManaCost(d)+' mana':''}</span></div><p class="loot-primary">${esc(primary)}</p>${d.consumableRework?'<small class="loot-affinity">Consumed on use · stacks to 5</small>':off?'<small class="loot-affinity">⚠ Off-class: +50% cooldown'+(d.group==='ability'?', +1 mana':'')+'</small>':'<small class="loot-affinity compatible">✓ Class compatible</small>'}<div class="loot-actions"><button onclick="${inspect}('${id}')" aria-label="Inspect ${esc(d.name)}">Inspect</button><button class="gold" title="${room?'':STASH_FULL_MESSAGE}" ${!room||shop&&s.gold<d.price?'disabled':''} onclick="${take}('${id}')" aria-label="${shop?'Buy':'Take'} ${esc(d.name)}">${shop?'Buy · '+d.price+'g':'Take item'}</button></div></article>`}
function inspectReward(id){if(s.phase!=='reward'||!reward.includes(id))return;modal(defs[id].name,'Full effects and class compatibility. You can return without choosing.',`<div class="loot-inspect-content">${itemCard(id,`takeLoot('${id}')`).replace(/^<button/,'<div').replace(/ onclick="[^"]*"/,'').replace(/<\/button>$/,'</div>')}</div><div class="loot-inspect-footer"><button onclick="showRewards()">← Back to all loot</button> <button class="gold" onclick="takeLoot('${id}')">Take this item</button></div>`,'rewardinspect')}
function showRewards(){if(s.lootChoiceDone)return showSupplies();modal('Victory. Choose your spoils.',reward.some(id=>defs[id].isShiny)?'✦ A very rare Shiny appeared! Take one item for your stash.':'Choose one item for your stash. Inspect for full effects.',`<div class="loot-grid" style="--loot-count:${Math.min(4,Math.max(1,reward.length))}">${reward.map(rewardCard).join('')}</div><div class="loot-footer"><button onclick="showSupplies()">${s.pendingSupplies?.length?'Unclaimed supplies · '+s.pendingSupplies.length:'Manage inventory'}</button><span>Choose one · All other items are left behind</span><button onclick="takeLoot(null)">Leave loot · recover ${Math.max(6,Math.round(s.max*.06))} health</button></div>`,'reward')}
function inspectShop(id){if(s.phase!=='shop'||!stock.includes(id))return;const d=defs[id];modal(d.name,'Inspect this offer. Your gold is only spent when you buy.',`<div class="shop-inspect-summary">${art(id)}<div><p>${esc(describe(d))}</p><small>${d.w}×${d.h} · ${itemTiming(d)} · ${itemManaCost(d)} mana</small></div></div><div class="shop-inspect-sections">${affinityNote(d)}${d.mechanic||d.realmSet?mechanicCard(d):d.bonus?`<p class="synergy">${esc(d.condition)}: +${d.bonus} ${['damage','drain','block','heal'].includes(d.effect)?d.effect:'damage'}.</p>`:''}${adjacencyGuide(d)}${shinyInfo(d)}</div><div class="shop-footer"><button onclick="showShop()">← Back to shop</button><button class="gold" ${s.gold<d.price?'disabled':''} onclick="buy('${id}')">Buy · ${d.price} gold</button></div>`,'shopinspect')}
function showShop(){if(s.phase!=='shop')return;const unavailable=(s.shopHeals||0)>=1||s.gold<25||s.hp>=s.max,m=currentShopSpecialist();modal(m?.name||'The wandering trader',`${s.gold} gold · ${shopSpecialistNote(m)}`, `<div class="shop-banner">${m?specialistShopScene({shopKind:m.kind}):eventScene('shop')}</div><div class="shop-offers" style="--shop-count:${Math.max(1,stock.length)}">${stock.map(id=>rewardCard(id,'shop')).join('')||'<p class="shop-empty">All offers purchased.</p>'}</div><div class="shop-footer"><button ${shopRefreshUsed()?'disabled':''} onclick="refreshShop()">${shopRefreshUsed()?'Refresh used':'Refresh stock · Free (1)'}</button><button ${unavailable?'disabled':''} onclick="buyHeal()">${(s.shopHeals||0)>=1?'Healing sold out':'Heal 25 HP · 25g'}</button><button class="gold" onclick="leaveShop()">Continue descent ↗</button></div>`,'shop')}

function showHelp(){modal('How to play','Pack your gear. Pick your route. See how far you get.',`<div class="quick-guide"><div><b>1 · Pack</b><p>Only items in your backpack work in battle. Keep spare gear in the nine-slot stash.</p></div><div><b>2 · Find a combo</b><p>Hover over gear to see its effects. Put matching items beside each other for bonuses.</p></div><div><b>3 · Fight</b><p>Press Begin battle. Your items activate on their own; you can rearrange them afterward.</p></div><div><b>4 · Keep going</b><p>Take loot, visit merchants and choose your next path. More skulls mean a tougher dungeon.</p></div></div><p class="quick-controls">Drag to move · R to rotate · S to stash<br>Hover over your character or enemy for details.</p><div class="hint-settings"><button data-hints-toggle onclick="toggleGameplayHints()"></button><button onclick="resetGameplayHints()">Show tips again</button></div><button class="gold" onclick="closeModal()">Back to game</button>`,'help');if(typeof syncGameplayHintControls==='function')syncGameplayHintControls()}
function openCatalogue(){catalogueOpen=true;catalogueState.page=0;drawCatalogue()}
function catalogueFilter(key,value){catalogueState[key]=value;catalogueState.page=0;drawCatalogue(true,key)}
const referenceSizes={catalogue:12,bestiary:12};
let referenceFiltersOpen=false,bestiaryDungeon='',bestiaryRole='',referenceReturnFocus='';
function referenceFocus(){if(window.__TEST__)return null;const el=document.activeElement;return el?.id?{id:el.id,start:el.selectionStart,end:el.selectionEnd}:null}
function referenceRestoreFocus(f){if(!f||window.__TEST__)return;const el=$(f.id);if(!el)return;el.focus({preventScroll:true});if(typeof f.start==='number'&&el.setSelectionRange)el.setSelectionRange(f.start,f.end)}
function itemUnobtainable(d){return !!(d&&(d.lootExcluded||d.daggerUnavailable||d.catalogueHidden))}
function itemAvailabilityNote(d){return itemUnobtainable(d)?'<p class="item-unavailable-note"><strong>Unobtainable</strong> · Cannot be obtained during gameplay. Existing saved copies remain usable.</p>':''}
function catalogueMatches(){const q=catalogueState;return DATA.items.filter(d=>((q.availability||'obtainable')==='all'||itemUnobtainable(d)===((q.availability||'obtainable')==='unobtainable'))&&(!q.search||(d.name+' '+(d.mechanic?.title||'')+' '+(d.mechanic?.text||'')).toLowerCase().includes(q.search.toLowerCase()))&&(!q.group||d.group===q.group)&&(!q.classId||d.classes.includes(q.classId))&&(!q.variant||(q.variant==='shiny'?d.isShiny:!d.isShiny))&&(!q.mechanic||d.mechanic?.key===q.mechanic))}
function referencePagination(kind,page,total,size){const pages=Math.max(1,Math.ceil(total/size));return `<nav class="reference-pagination" aria-label="${kind==='catalogue'?'Item':'Encounter'} result pages"><button ${!page?'disabled':''} onclick="referenceGoPage('${kind}',${page})">← Previous</button><label>Page <input id="referencePageNumber" aria-label="Page number" type="number" min="1" max="${pages}" value="${page+1}" onchange="referenceGoPage('${kind}',this.value)"> of ${pages.toLocaleString()}</label><button ${page>=pages-1?'disabled':''} onclick="referenceGoPage('${kind}',${page+2})">Next →</button></nav>`}
function returnReference(kind){if(kind==='catalogue')drawCatalogue();else drawBestiary();if(!window.__TEST__)document.getElementById(referenceReturnFocus)?.focus({preventScroll:true})}
function referenceGoPage(kind,value){const total=kind==='catalogue'?catalogueMatches().length:bestiaryMatches().length,size=referenceSizes[kind],page=Math.max(0,Math.min(Math.max(0,Math.ceil(total/size)-1),(parseInt(value,10)||1)-1));if(kind==='catalogue'){catalogueState.page=page;drawCatalogue()}else{bestiaryPage=page;drawBestiary()}}
function referenceSummary(total,page,size,noun){return total?`${(page*size+1).toLocaleString()}–${Math.min(total,(page+1)*size).toLocaleString()} of ${total.toLocaleString()} ${noun}`:`No matching ${noun}`}
function toggleReferenceFilters(){referenceFiltersOpen=!referenceFiltersOpen;const panel=$('referenceFilters'),button=$('referenceFilterToggle');if(panel){panel.dataset.open=String(referenceFiltersOpen);button.setAttribute('aria-expanded',String(referenceFiltersOpen))}}
function resetReferenceFilters(kind){if(kind==='catalogue'){Object.assign(catalogueState,{search:'',group:'',classId:'',variant:'',mechanic:'',availability:'obtainable',page:0});drawCatalogue()}else{bestiarySearch='';bestiaryDungeon='';bestiaryRole='';bestiaryPage=0;drawBestiary()}}
function drawCatalogue(preserveFocus=false,focusKey=''){
 const focus=referenceFocus(),q=catalogueState,filtered=catalogueMatches(),size=referenceSizes.catalogue,pages=Math.max(1,Math.ceil(filtered.length/size));q.page=Math.max(0,Math.min(q.page,pages-1));const current=filtered.slice(q.page*size,(q.page+1)*size),active=[q.group,q.classId,q.variant,q.mechanic].filter(Boolean).length+Number((q.availability||'obtainable')!=='obtainable');
 modal('Item compendium','Compare equipment and signatures. Inspect a card for its full rules.',`
 <div class="reference-tools"><input id="catalogueSearch" aria-label="Search items" placeholder="Search names or mechanics…" value="${esc(q.search)}" oninput="catalogueFilter('search',this.value)"><button id="referenceFilterToggle" class="reference-filter-toggle" aria-expanded="${referenceFiltersOpen}" aria-controls="referenceFilters" onclick="toggleReferenceFilters()">Filters${active?' · '+active:''}</button><button onclick="closeCatalogue()">Close ✕</button></div>
 <div class="reference-filters" id="referenceFilters" data-open="${referenceFiltersOpen}">
 <label>Availability<select id="catalogueAvailability" onchange="catalogueFilter('availability',this.value)"><option value="obtainable" ${q.availability==='obtainable'?'selected':''}>Obtainable</option><option value="unobtainable" ${q.availability==='unobtainable'?'selected':''}>Unobtainable</option><option value="all" ${q.availability==='all'?'selected':''}>All items</option></select></label>
 <label>Item type<select id="catalogueGroup" onchange="catalogueFilter('group',this.value)"><option value="">All types</option>${['weapon','ability','armor','ring','consumable'].map(g=>`<option value="${g}" ${q.group===g?'selected':''}>${g}</option>`).join('')}</select></label>
 <label>Class<select id="catalogueClass" onchange="catalogueFilter('classId',this.value)"><option value="">All classes</option>${Object.values(classes).map(c=>`<option value="${c.id}" ${q.classId===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label>
 <label>Version<select id="catalogueVariant" onchange="catalogueFilter('variant',this.value)"><option value="">All versions</option><option value="regular" ${q.variant==='regular'?'selected':''}>Regular</option><option value="shiny" ${q.variant==='shiny'?'selected':''}>Shiny</option></select></label>
 <label>Signature<select id="catalogueMechanic" onchange="catalogueFilter('mechanic',this.value)"><option value="">All mechanics</option>${[...new Map(DATA.items.filter(d=>d.mechanic).map(d=>[d.mechanic.key,d.mechanic.title])).entries()].sort((a,b)=>a[1].localeCompare(b[1])).map(([key,title])=>`<option value="${key}" ${q.mechanic===key?'selected':''}>${esc(title)}</option>`).join('')}</select></label><button onclick="resetReferenceFilters('catalogue')">Reset</button><button class="reference-filter-done" onclick="toggleReferenceFilters()">Done</button></div>
 <div class="reference-summary"><span>${referenceSummary(filtered.length,q.page,size,'items')}</span><span id="referenceNotification" role="status">${s?.practice?'Sandbox · + Stash to try gear':'Inspect to compare'}</span></div>
 <div class="reference-grid" data-reference="catalogue">${current.map(d=>`<article class="reference-card ${d.isShiny?'shiny':''}" data-reference-id="${d.id}"><div class="reference-card-heading">${art(d.id)}<div><h3 title="${esc(d.name)}">${esc(d.name)}</h3><small>${d.rarity} · ${esc(d.tier)} · ${esc(d.kind)}</small></div></div><p class="reference-card-summary" title="${esc(describe(d))}">${esc(describe(d))}</p><div class="reference-card-meta"><span>${d.w}×${d.h} · ${itemTiming(d)} · ${itemManaCost(d)} mana</span>${itemUnobtainable(d)?'<span class="item-unavailable-badge" title="Cannot be obtained during gameplay">Unobtainable</span>':`<span class="${isOffClass(d)?'offclass':'compatible'}">${isOffClass(d)?'Off-class':'Compatible'}</span>`}</div><div class="reference-card-actions"><button id="referenceInspect_${d.id}" onclick="inspectCatalogueItem('${d.id}')">Inspect</button>${s?.practice?`<button ${s.phase!=='prep'||itemUnobtainable(d)?'disabled':''} onclick="addSandbox('${d.id}')">${itemUnobtainable(d)?'Unobtainable':'+ Stash'}</button>`:''}</div></article>`).join('')||`<div class="reference-empty"><h2>No matching items</h2><p>Try a shorter search or reset the filters.</p><button onclick="resetReferenceFilters('catalogue')">Reset search & filters</button></div>`}</div>
 ${referencePagination('catalogue',q.page,filtered.length,size)}`,'catalogue');
 referenceRestoreFocus(focus);if(preserveFocus&&focusKey==='search'&&!window.__TEST__){const input=$('catalogueSearch');input.focus();input.setSelectionRange(input.value.length,input.value.length)}
}
function catalogueItemMarkup(d){
 const native=Array.isArray(d.classes)?d.classes:[],names=native.map(id=>classes[id]?.name||id).join(', '),off=isOffClass(d),affinity=d.group==='ring'||d.group==='consumable'||!native.length||native.length===Object.keys(classes).length?'':`<p class="catalogue-item-affinity ${off?'offclass':''}"><b>${off?'Off-class':'Class compatible'}</b> · ${esc(names)}${off?`<br>Cooldown +50%: ${d.cd}s → ${itemTiming(d)}${d.group==='ability'?` · Mana +1: ${d.mana} → ${itemManaCost(d)}`:''}`:''}</p>`;
 const repeated=d.mechanic&&!d.realmSet&&describe(d).includes(realmText(d,d.mechanic.text)),effect=repeated?'':d.mechanic?mechanicCard(d,false):d.bonus?`<p class="synergy">${esc(d.condition)}: +${d.bonus} ${esc(d.effect)}.</p>`:'',placement=adjacencyGuide(d);
 return `<div class="catalogue-item-content"><div class="catalogue-item-grid"><section class="catalogue-item-overview"><div class="catalogue-item-stats">${art(d.id)}<div><b>${d.w}×${d.h} cells · ${passiveRing(d)?'Passive':itemTiming(d)+' cooldown'}</b><span>${itemManaCost(d)} mana · ${d.consumableRework?'Permanently consumed after use':passiveRing(d)?'Passive while packed':d.once?'Single use per copy · stacks to five':'Repeats automatically'}</span></div></div>${itemAvailabilityNote(d)}<p class="catalogue-item-description">${esc(describe(d))}</p>${affinity}${d.isShiny?`<details class="catalogue-item-extra"><summary>Shiny comparison</summary>${shinyInfo(d)}</details>`:''}</section><section class="catalogue-item-effects">${effect}</section></div>${d.realmSet?`<section class="catalogue-item-set">${realmSetMarkup(d)}</section>`:''}${placement?`<details class="catalogue-item-extra catalogue-item-placement"><summary>Placement and adjacency rules</summary>${placement}</details>`:''}</div><footer class="catalogue-item-footer"><a href="${d.source}" target="_blank" rel="noopener">Wiki ↗</a><button onclick="returnReference('catalogue')">← Back to catalogue</button></footer>`
}
function inspectCatalogueItem(id){const d=defs[id];if(!d)return;referenceReturnFocus='referenceInspect_'+id;modal(esc(d.name),`${d.rarity} · ${esc(d.tier)} · ${esc(d.kind)}`,catalogueItemMarkup(d),'catalogueinspect')}
function cataloguePage(delta){catalogueState.page+=delta;drawCatalogue()}
function closeCatalogue(){catalogueOpen=false;restorePhaseModal()}
function addSandbox(id){if(!s.practice||s.phase!=='prep'||!defs[id]||itemUnobtainable(defs[id]))return;if(!receiveItem(makeItem(id)))return;save();render();toast(defs[id].name+' added to your stash.')}
function render(){syncRingVitals();if(window.__TEST__)return;if(!s)return;const trash=$('inventoryTrash');if(trash)trash.disabled=s.phase!=='prep';flushJournal();const r=ROOMS[s.room],c=classes[s.classId];updateBattleFloor(r);$('roomtitle').textContent=r.name;$('roomtype').textContent=`ROOM ${String(s.room+1).padStart(2,'0')} / 07`;$('ename').textContent=r.enemy;if(!r.sprite){$('enemySprite').textContent=r.icon;$('enemySprite').dataset.sprite='';}setBattleSprite('playerSprite',c.sprite,c.name);$('playerName').textContent=c.name;updateClassPanel(c);$('status').textContent=(s.practice?'SANDBOX · ':'')+(s.phase==='fight'?'● Battle in progress':s.phase==='prep'?'● Preparing for battle':s.phase==='won'?'✦ Vault conquered':s.phase==='lost'?'Run ended':'● Choose your next step');$('phase').textContent=s.phase==='fight'?'EQUIPMENT ACTIVATING AUTOMATICALLY':s.phase==='prep'?(r.type==='event'?'NON-COMBAT ENCOUNTER':'PREPARE YOUR LOADOUT'):s.phase.toUpperCase();$('fight').disabled=s.phase==='fight';$('fight').textContent=s.phase==='fight'?'Fighting…':['won','lost'].includes(s.phase)?'New run ↻':s.phase!=='prep'?'Continue ↗':['shop','rest','event'].includes(r.type)?'Enter room ↗':'Begin battle ↗';$('capacity').textContent=s.items.reduce((a,i)=>{const [w,h]=dims(i);return a+w*h},0)+' / 30 CELLS';renderBackpack();renderDetail();updateStats()}
function itemInspectionMarkup(i){const d=defs[i.type],[w,h]=dims(i);return `<div class="label" style="color:${d.color}">${d.rarity} · ${esc(d.tier)} · ${esc(d.kind)}${itemUnobtainable(d)?' · Unobtainable':''}</div><div class="detailtitle"><span>${art(i.type)}</span><h2>${esc(d.name)}</h2></div><div class="stats"><span>▦ ${w}×${h}</span><span>◷ ${itemTiming(d,i)}</span><span>✦ ${itemManaCost(d,i)} mana</span></div>${itemAvailabilityNote(d)}<p>${esc(describe(d))}</p>${shinyInfo(d)}${affinityNote(d)}${d.mechanic||d.realmSet?mechanicCard(d):d.bonus?`<p class="synergy">${esc(d.condition)}: +${d.bonus} ${['damage','drain','block','heal'].includes(d.effect)?d.effect:'damage'}.</p>`:''}${infusionMarkup(i)}${potionUpgradeMarkup(i)}${consumableControls(i)}${stackDetail(i)}${adjacencyGuide(d)}${enchantMarkup(i)}${itemEffectsDetail(i)}${i.eventHaste?`<p class="synergy">Tempered this run: ${Math.round(i.eventHaste*100)}% shorter cooldown.</p>`:''}<div class="label" id="signatureMeter"></div><small>${s.items.includes(i)?'Packed and active':'Stashed and inactive'} · ${d.consumableRework?'Permanently consumed after use':passiveRing(d)?'Passive while packed':d.once?'One use per copy per battle':'Repeats automatically'}</small><div style="margin-top:12px"><button onclick="discardSelected(${i.id})" style="padding:6px 10px">Discard</button> <a href="${d.source}" target="_blank" rel="noopener">Wiki ↗</a></div>`}
function closeItemDetails(){closeModal(true);document.querySelector('#detail .inspection-actions button')?.focus({preventScroll:true})}
function showItemDetails(id){const i=[...s.items,...s.stash].find(i=>i.id===id);if(!i)return;modal(esc(defs[i.type].name),'Item effects, enchantments and connections.',itemInspectionMarkup(i).replace('id="signatureMeter"','id="detailSignatureMeter"').replace('id="stackUses"','id="detailStackUses"').replaceAll('onclick="splitSelectedStack','onclick="closeModal(true);splitSelectedStack')+'<button class="gold" onclick="closeItemDetails()">Back to game</button>','itemdetails')}
function renderDetail(){
 const i=findInspected();if(!i){$('detail').innerHTML='<p>Hover, focus or select an item to inspect it.</p>';return}
 const d=defs[i.type],[w,h]=dims(i),rules=ADJACENCY_RULES.filter(r=>r.target(d));
 $('detail').innerHTML=`<div class="inspection-heading"><div class="label" style="color:${d.color}">${d.rarity} · ${esc(d.tier)} · ${esc(d.kind)}${itemUnobtainable(d)?' · Unobtainable':''}</div><div class="detailtitle"><span>${art(i.type)}</span><h2>${esc(d.name)}</h2></div><div class="stats"><span>▦ ${w}×${h}</span><span>◷ ${itemTiming(d,i)}</span><span>✦ ${itemManaCost(d,i)} mana</span></div></div><p class="inspection-description">${esc(describe(d))}</p>${isOffClass(d)?`<p class="inspection-affinity">⚠ Off-class · +50% cooldown${d.group==='ability'?' · +1 mana':''}</p>`:''}<div class="inspection-extras">${potionUpgradeMarkup(i)}${rules.length?`<section class="inspection-adjacency"><b>Adjacency bonuses</b>${rules.map(r=>{const copy=adjacencyCopy(r);return `<p><strong>${esc(copy.bonus)}</strong> ${esc(copy.neighbor)}</p>`}).join('')}</section>`:''}${enchantMarkup(i)}${d.mechanic?`<p class="inspection-signature">✧ ${esc(d.mechanic.title)}</p>`:''}</div>${d.once?`<div class="inspection-stack">Stack ${stackCount(i)} / 5 · <span id="stackUses">${s.phase==='fight'?stackRemaining(i):stackCount(i)}</span> ${s.phase==='fight'?'uses left':d.consumableRework?'copies remaining':'uses per battle'}${stackCount(i)>1?`<button onclick="splitSelectedStack(${i.id})" ${s.phase!=='prep'||s.stash.length>=STASH_LIMIT?'disabled':''}>Split one into stash</button>`:''}</div>`:''}<div class="label" id="signatureMeter"></div>${consumableControls(i)}<div class="inspection-actions"><button onclick="showItemDetails(${i.id})">Full details</button><button onclick="discardSelected(${i.id})" ${s.phase!=='prep'?'disabled':''}>Discard</button></div>`
}

const uiStyleValues=new WeakMap();
function setTextValue(node,value){value=String(value);if(node&&node.textContent!==value)node.textContent=value}
function setStyleValue(node,key,value){if(!node)return;value=String(value);let values=uiStyleValues.get(node);if(!values){values=new Map();uiStyleValues.set(node,values)}const old=values.get(key);if(old?.value===value&&node.style[key]===old.actual)return;node.style[key]=value;values.set(key,{value,actual:node.style[key]})}
