function tick(dt){if(!Number.isFinite(dt)||dt<=0||s.phase!=='fight'||catalogueOpen||bestiaryOpen||['help','runmap','menu','devnotes'].includes(modalKind))return;for(let remaining=dt;remaining>1e-8&&s.phase==='fight';remaining-=.05)tickCombatStep(Math.min(.05,remaining));if(s.phase==='fight')updateStats()}
function tickCombatStep(dt){if(s.phase!=='fight'||catalogueOpen||bestiaryOpen||(modalKind==='help'||modalKind==='runmap'||modalKind==='menu'||modalKind==='devnotes'))return;prepareCombatGeometry();combatGeometryTick=true;try{const e=s.enemy,previous=Math.floor(s.time),r=ROOMS[s.room];s.time+=dt;const frozenStep=Math.min(dt,e.frozen||0);e.frozen=Math.max(0,(e.frozen||0)-dt);tickItemMechanics(dt);tickClassEffects(dt);s.haste=Math.max(0,s.haste-dt);for(const i of s.items)i.hasteRemaining=Math.max(0,(i.hasteRemaining||0)-dt);s.silence=Math.max(0,s.silence-dt);s.slow=Math.max(0,s.slow-dt);s.venomTime=Math.max(0,s.venomTime-dt);if(!s.venomTime)s.venom=0;e.veil=Math.max(0,e.veil-dt);for(const key of ['chill','weaken','vulnerable','poisonTime','bleedTime'])e[key]=Math.max(0,e[key]-dt);if(!e.poisonTime)e.poison=0;if(!e.bleedTime)e.bleed=0;passive('time',dt);if(s.classId==='kensei'){s.kenseiTime+=dt;if(s.kenseiTime>=8){s.kenseiTime-=8;s.dodge=Math.min(3,s.dodge+1)}}for(const pet of s.summons)pet.duration-=dt;s.summons=s.summons.filter(p=>p.duration>0);if(r.type==='boss'&&!e.phaseTwo&&e.hp<=e.max/2){e.phaseTwo=true;e.damage=Math.round(e.damage*1.2);log('BOSS PHASE II: '+(r.secondary?ENCOUNTERS.profiles[r.secondary].name:'Enraged')+' joins the battle pattern!');flash('enemySprite')}
if(Math.floor(s.time)>previous){s.block=Math.max(0,Math.floor(s.block*.9));if(!s.silence&&!wandManaSuppressed())s.mana=Math.min(manaCapacity(),s.mana+1);const status=e.burn+e.poison+e.bleed;if(status){hit(Math.round(status*(r.type==='boss'?.7:r.type==='elite'?.85:1)));e.burn=Math.max(0,e.burn-1);e.poison=Math.max(0,e.poison-1);e.bleed=Math.max(0,e.bleed-1);log('Afflictions deal '+status+' damage.')}if(s.summons.length){const amount=abilityCompanionDamage();if(amount>0){hit(amount);log('Companions deal '+amount+' damage.')}realmCompanionHealing()}if(e.hp>0&&!frozenStep)encounterSecond()}
if(s.hp>0)for(const i of s.items){if(e.hp<=0)break;if(s.silence&&!realmCanCleanse(i))continue;if(i.used||passiveRing(defs[i.type])&&!ringCanActivate(i)||consumableProfile(i)&&!['supply','legacy','freeze'].includes(consumableProfile(i).mode))continue;const cycle=cooldown(i);i.charge=i.charge+1e-8>=cycle?cycle:i.charge+wandRechargeStep(i,dt);if(i.charge+1e-8>=cycle){const excess=Math.max(0,i.charge-cycle);if(activate(i))i.charge=defs[i.type].once?0:Math.min(excess,cooldown(i));else i.charge=cycle}}if(s.hp<=0||s.time>=150)return finishBattle(false);if(e.hp<=0)return finishBattle(true);let rate=e.chill>0?1/1.35:1;if(enemyProfiles().includes('berserker')&&e.hp<e.max/2)rate*=1.25;e.charge+=(dt-frozenStep)*rate;if(e.charge>=e.cd){e.charge-=e.cd;enemyAttack()}if(s.hp<=0)return finishBattle(false);if(e.hp<=0)return finishBattle(true)}finally{combatGeometryTick=false}}
function finishBattle(victory){if(!victory&&tryItemRescue())return;const r=ROOMS[s.room];if(victory){daggerEnemyDefeated();specialRingEnemyDefeated();armorEnemyDefeated();abilityEvent('kill',1);}if(victory&&s.enemy.wave<(r.waves||1)){s.enemy.wave++;s.enemy.hp=s.enemy.max;setupWave();log('Wave '+s.enemy.wave+' / '+r.waves+' approaches.');updateStats();return}clearInterval(timer);finishConsumableEffects(victory);if(victory){awardCombatSupplies();awardEnchantDust(r);s.kills++;s.gold+=r.gold??14;if(r.type==='boss')s.bosses++;s.history.push({depth:s.room+1,encounter:r.encounterId,victory:true});log('Victory! +'+(r.gold??14)+' gold.');s.phase='reward';reward=rollLoot(r.type==='boss'?4:3);render();save();showRewards()}else{s.history.push({depth:s.room+1,encounter:r.encounterId,victory:false});s.phase='lost';s.endedAt=Date.now();render();save();showEnding()}}
const SHINY_RATES={combat:1/500,elite:1/250,boss:1/100};
function shinyUpgrade(id,role,random=rng){const d=defs[id],variants=DATA.shinyByBase[id];if(!d||d.isShiny||!variants?.length)return id;const chance=SHINY_RATES[role]||0;if(!chance||random()>=chance)return id;return variants[Math.min(variants.length-1,Math.floor(random()*variants.length))]}
function lootRarityWeights(role,act){const base=act<=0?[.60,.32,.075,.005]:act===1?[.15,.55,.27,.03]:[.02,.28,.55,.15];if(role==='boss')return act<=0?[.02,.23,.60,.15]:[0,.05,.55,.40];if(role==='elite')return act<=0?[.08,.47,.40,.05]:[0,.15,.60,.25];return base}
function rollLoot(n,context='drop'){if(context==='shop')return rollSpecialistStock(n,currentShopSpecialist()?.kind||ROOMS[s.room].shopKind||chooseShopKind());const c=classes[s.classId],r=ROOMS[s.room],role=context==='shop'?'shop':r.risk?'elite':r.type,weights=lootRarityWeights(role,actIndex()),eligible=DATA.items.filter(d=>!d.isShiny&&!d.lootExcluded),chosen=[],used=new Set();for(let slot=0;slot<n;slot++){let roll=rng(),quality=3;for(let q=0;q<weights.length;q++){roll-=weights[q];if(roll<0){quality=q;break}}let pool=eligible.filter(d=>d.quality===quality&&!used.has(d.id));if(!pool.length)pool=eligible.filter(d=>!used.has(d.id));if(!pool.length)break;if(context==='drop'&&s.consumableRewardMods?.lootDrop&&rng()<.25){const special=eligible.filter(d=>['UT','ST'].includes(d.tier)&&!used.has(d.id));if(special.length)pool=special}let total=pool.reduce((sum,d)=>sum+(d.classes.includes(c.id)?3:1),0),target=rng()*total,picked=pool[pool.length-1];for(const d of pool){target-=d.classes.includes(c.id)?3:1;if(target<0){picked=d;break}}if(context==='drop'&&s.consumableRewardMods?.lootTier&&/^T[0-9]+$/.test(picked.tier)&&rng()<.5){const higher=eligible.filter(d=>d.kind===picked.kind&&d.group===picked.group&&d.balanceFamily===picked.balanceFamily&&/^T[0-9]+$/.test(d.tier)&&d.progressionRank>picked.progressionRank&&!used.has(d.id));if(higher.length)picked=higher[Math.floor(rng()*higher.length)]}used.add(picked.id);chosen.push(context==='shop'?picked.id:shinyUpgrade(picked.id,r.type))}return chosen}

function shinyInfo(d){if(d.armorIdentity&&d.isShiny)return '<div class="shiny-note"><b>✦ SHINY VARIANT</b><p>5% stronger positive armor stats and faster activation. Same source conditions, proc budgets and shared cooldowns.</p></div>';if(d.specialRingIdentity&&d.isShiny)return specialRingShinyMarkup(d);if(d.daggerUnavailable)return '<p class="effect-note">Temporarily unobtainable. Existing saved copies remain usable.</p>';if(!d.isShiny)return '';const base=defs[d.baseId];return `<div class="shiny-note"><b>✦ SHINY VARIANT</b><p>Special version of ${esc(base.name)}. ${d.daggerUpdate?'Same size and identity, with stronger primary/signature values and a faster cooldown.':'Same size, mana cost, effects and synergies, with a faster cooldown.'} Compare its primary effect below.</p><small>Regular → Shiny: ${base.cd}s → ${d.cd}s · ${base.amount} → ${d.amount} ${esc(d.effect)}</small><p>Eligible reward upgrade chance: 1/500 normal · 1/250 elite · 1/100 boss. Drop-only in normal runs.</p></div>`}

function takeLoot(id){if(s.phase!=='reward'||s.lootChoiceDone||id&&!reward.includes(id))return;if(id){if(!daggerAvailable(id)||defs[id]?.lootExcluded)return toast('This item is currently unavailable.');if(!receiveItem(makeItem(id)))return;log('Acquired '+defs[id].name+'.')}else restore(Math.max(6,Math.round(s.max*.06)),false);s.lootChoiceDone=true;reward=[];save();continueRewardSupplies()}
function showBoon(){modal('Claim a boss blessing','Every boss grants a permanent benefit for this run. Each blessing also restores 15% of your maximum health.',`<div class="choices"><button class="choice" onclick="takeBoon('power')"><b>⚔ Oryx’s Might</b><p>Start every battle with +2 damage power.</p></button><button class="choice" onclick="takeBoon('haste')"><b>✧ Crystal Tempo</b><p>Your entire backpack recharges 6% faster (stacks to 48%).</p></button><button class="choice" onclick="takeBoon('life')"><b>♡ Ancient Vitality</b><p>Gain 12 maximum health and restore 12 additional health.</p></button></div>`,'boon')}
function takeBoon(choice){if(s.phase!=='boon'||!['power','haste','life'].includes(choice))return;if(choice==='power')s.relicPower+=2;else if(choice==='haste')s.relicHaste=Math.min(.48,(s.relicHaste||0)+.06);else{s.max+=12;s.hp+=12}s.boons.push(choice);restore(Math.round(s.max*.15),false);nextRoom()}
function nextRoom(){selected=null;reward=[];stock=[];s.room++;if(s.room>=ROOMS.length){s.room=ROOMS.length-1;s.phase='won';render();save();showEnding();return}s.phase='prep';closeModal(true);if(s.room%10===0){setEnemy();render();preparePortal();return}if(ROOMS[s.room].type==='combat'){preparePath();return}setEnemy();render();save()}
function preparePath(){ensureActMap();s.pathChoices=s.mapBranches[s.room]||[ROOMS[s.room]];s.phase='path';save();showPath()}
function showPath(){modal('Choose your path',`Depth ${s.room+1} · ${dungeonDefs[s.dungeons[actIndex()]].name}. Preview the threat before committing.`,`<div class="map-dungeon-rating">${dungeonDifficultyBadge(s.dungeons[actIndex()])}</div><button onclick="showRunMap()">View branching map ↗</button><div class="choices">${s.pathChoices.map((r,n)=>`<button class="choice" onclick="selectPath(${n})">${r.type==='event'?`<div class="event-path-icon">${eventScene(r.eventId,'path')}</div><b>${esc(r.name)}</b><small>Non-combat encounter</small><p>${esc(noncombatById[r.eventId].desc)}</p><strong>Trades, risks, and run rewards</strong>`:`${spriteMarkup(r.sprite,r.enemy,'portalpixel')}<b>${n?'Dangerous passage':encounterDangerText(r)?'Challenging passage':'Steady passage'}</b><small>${esc(r.enemy)} · ${r.hp} HP · ${r.damage} damage</small>${encounterDangerBadge(r)}<p>${esc(encounterProfileDescription(r))}</p><strong>${r.gold} gold${n?' · better odds of rare loot':''}</strong>`}</button>`).join('')}</div>`,'path')}
function selectPath(n){if(s.phase!=='path'||!s.pathChoices[n])return;s.mapTaken=s.mapTaken||{};s.mapTaken[s.room]=n;ROOMS[s.room]=s.pathChoices[n];s.route=ROOMS;s.phase='prep';closeModal(true);setEnemy();render();save()}
function resolveRest(choice){if(s.phase!=='rest')return;if(choice==='heal')restore(Math.round(s.max*.3),false);else if(choice==='max'){s.max+=10;s.hp+=10}else return;nextRoom()}
function showRest(){modal('A quiet refuge','Prepare for the chambers ahead. Health persists through the descent.',`${eventScene('rest')}<div class="choices"><button class="choice" onclick="resolveRest('heal')"><b>Rest by the fire</b><p>Restore ${Math.round(s.max*.3)} health (30% of maximum).</p></button><button class="choice" onclick="resolveRest('max')"><b>Train your resolve</b><p>Gain 10 maximum health and restore 10 health.</p></button></div>`,'rest')}
function continueEndless(){if(s.phase!=='won')return;const start=ROOMS.length;ROOMS.push(...emptyRoute(start));s.route=ROOMS;s.room=start;s.phase='prep';s.hp=s.max;setEnemy();closeModal(true);render();preparePortal()}
function showDefeat(){
 if(!window.__TEST__){$('toast').style.display='none';clearTimeout(toastTimer);if(typeof hideGameplayHintPointer==='function')hideGameplayHintPointer()}
 const character=classes[s.classId],room=ROOMS[s.room],depth=s.room+1,act=Math.floor(s.room/10)+1;
 const date=Number.isFinite(s.endedAt)?new Date(s.endedAt).toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Helsinki'}):'';
 const cause=s.hp>0&&s.time>=150?'Time ran out against':'Killed'+(date?' on '+date:'')+' by';
 modal('Dead!',`${cause} ${room.enemy||room.name}`,`<div class="defeat-portrait" aria-label="${esc(character.name)}">${spriteMarkup(character.sprite,character.name,'defeat-sprite')}</div><div class="defeat-progress"><span>Depth reached</span><strong>${depth}</strong><small>Act ${act} · Room ${s.room%10+1} of 10</small></div><dl class="defeat-stats"><div><dt>Class</dt><dd>${esc(character.name)}</dd></div><div><dt>Mode</dt><dd>${s.practice?'Sandbox · ':''}${esc(difficulty().name)}</dd></div><div><dt>Victories</dt><dd>${s.kills}</dd></div><div><dt>Bosses defeated</dt><dd>${s.bosses}</dd></div><div><dt>Blessings</dt><dd>${s.boons.length}</dd></div><div><dt>Gold remaining</dt><dd>${s.gold}</dd></div></dl><div class="defeat-divider" aria-hidden="true"><span>◆</span></div><button class="defeat-continue" onclick="chooseClass()">Choose a new adventurer</button>`,'defeat')
}

function showEnding(){if(s.phase==='lost')return showDefeat();const won=s.phase==='won';modal(won?'The descent is conquered.':'The realm claims another.',`${classes[s.classId].name} · ${difficulty().name} · Depth ${s.room+1} · ${s.kills} victories · ${s.bosses} bosses`, `<p>${won?'Your three-act expedition is complete. Venture into another three acts with stronger enemies, or begin a fresh build.':'Every descent draws from 350 encounter configurations across 35 dungeon themes. Try a different path, class, or build.'}</p>${won?'<button class="gold" onclick="continueEndless()">Continue into endless descent ↗</button> ':''}<button onclick="chooseClass()">Choose a new adventurer</button>`,'ending')}
function restorePhaseModal(){if(s.phase==='reward'){if(s.lootChoiceDone)continueRewardSupplies();else showRewards()}else if(s.phase==='rest')showRest();else if(s.phase==='shop')showShop();else if(s.phase==='portal')showPortal();else if(s.phase==='path')showPath();else if(s.phase==='event')showEvent();else if(s.phase==='eventResult')showEventResult();else if(s.phase==='boon')showBoon();else if(['won','lost'].includes(s.phase))showEnding();else closeModal(true)}
function closeModal(force=false){if(!force&&['reward','rest','shop','portal','path','event','eventResult','boon','won','lost'].includes(s?.phase))return restorePhaseModal();catalogueOpen=false;bestiaryOpen=false;modalKind='';if(!window.__TEST__){$('overlay').innerHTML='';if(s?.phase==='fight')updateStats()}}
let classPreviewId=null,classSelectionPractice=false,classPreviewTab='overview',pendingClassStart=null,classStartRevision=0;
function chooseClass(practice=false){
 if(s?.phase==='fight')return;pendingClassStart=null;catalogueOpen=false;bestiaryOpen=false;classSelectionPractice=practice;
 if(!classes[classPreviewId])classPreviewId=s?.classId||'wizard';
 modal('Choose your adventurer','Hover or focus to compare. Click a class to start.',`<div class="class-switch roster-settings"><button class="${!practice?'gold':''}" aria-pressed="${!practice}" onclick="chooseClass(false)">Dungeon run</button><button class="${practice?'gold':''}" aria-pressed="${practice}" onclick="chooseClass(true)">Sandbox</button><select aria-label="Starting difficulty" onchange="selectedDifficulty=this.value">${Object.entries(DIFFICULTIES).map(([id,d])=>`<option value="${id}" ${id===selectedDifficulty?'selected':''}>${d.name} · ${d.hp}× enemy health</option>`).join('')}</select></div><div class="class-selection"><div class="class-roster" role="group" aria-label="All 19 classes">${Object.values(classes).map(c=>`<button class="roster-class" aria-label="${esc(c.name)}" data-class-id="${c.id}" aria-pressed="${c.id===classPreviewId}" aria-controls="classPreview" onpointerenter="if(event.pointerType!=='touch')previewClass('${c.id}')" onfocus="previewClass('${c.id}')" onclick="requestClassStart('${c.id}')">${spriteMarkup(c.sprite,c.name,'roster-sprite')}<span>${esc(c.name)}</span></button>`).join('')}</div><section class="class-preview" id="classPreview" aria-label="Class details"><nav class="class-preview-tabs" aria-label="Class details section"><button onclick="classPreviewSection('overview')" data-class-section="overview" aria-pressed="${classPreviewTab==='overview'}">Overview</button><button onclick="classPreviewSection('passive')" data-class-section="passive" aria-pressed="${classPreviewTab==='passive'}">Passive</button></nav><div id="classPreviewContent"></div></section></div><div class="class-selection-footer">${s?'<button onclick="closeModal()">Return to run</button>':'<span>19 adventurers</span>'}<span class="roster-click-hint">Click an adventurer to begin</span></div>`,'classes');
 if(!window.__TEST__)previewClass(classPreviewId)
}
function previewClass(id){
 const c=classes[id];if(!c||modalKind!=='classes')return;classPreviewId=id;
 document.querySelectorAll('.roster-class[data-class-id]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.classId===id)));
 $('classPreviewContent').innerHTML=`<div class="class-preview-heading">${spriteMarkup(c.sprite,c.name,'classpixel')}<div><h2>${esc(c.name)}</h2><strong>♥ ${c.hp} starting health</strong></div></div><div class="class-overview"><p>${esc(c.desc)}</p><div class="class-starting-gear" aria-label="Starting equipment">${c.startingIds.slice(0,3).map(id=>`<span title="${esc(defs[id].name)}">${art(id)}<small>${esc(defs[id].kind)}</small></span>`).join('')}</div></div><div class="class-passive"><h3>${esc(c.title)}</h3><p>${esc(c.rule)}</p></div>`;
 classPreviewSection(classPreviewTab)
}
function classPreviewSection(tab){classPreviewTab=tab==='passive'?'passive':'overview';const panel=$('classPreview');if(!panel)return;panel.dataset.section=classPreviewTab;panel.querySelectorAll('[data-class-section]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.classSection===classPreviewTab)))}
function requestClassStart(id){
 if(modalKind!=='classes'||s?.phase==='fight'||!classes[id])return false;
 classPreviewId=id;const request={id,practice:classSelectionPractice,difficulty:DIFFICULTIES[selectedDifficulty]?selectedDifficulty:'normal',revision:++classStartRevision};pendingClassStart=request;
 const c=classes[id],mode=request.practice?'Sandbox':'Dungeon run';
 modal('Start as '+c.name+'?',`${DIFFICULTIES[request.difficulty].name} · ${mode}.${s&&!['lost','won'].includes(s.phase)?' Starting replaces your current run.':''}`,`<button id="cancelClassStart" onclick="cancelClassStart(${request.revision})">Back to classes</button><button class="gold" id="confirmClassStart" onclick="confirmClassStart(${request.revision})">Start ${esc(c.name)} ↗</button>`,'classconfirm');return true
}
function cancelClassStart(revision=pendingClassStart?.revision){
 const request=pendingClassStart;if(modalKind!=='classconfirm'||!request||revision!==request.revision)return false;
 pendingClassStart=null;classPreviewId=request.id;chooseClass(request.practice);
 if(!window.__TEST__)document.querySelector('.roster-class[data-class-id="'+request.id+'"]')?.focus({preventScroll:true});return true
}
function confirmClassStart(revision){
 const request=pendingClassStart;if(modalKind!=='classconfirm'||!request||revision!==request.revision||s?.phase==='fight'||!classes[request.id])return false;
 pendingClassStart=null;selectedDifficulty=request.difficulty;freshRun(request.id,request.practice);return true
}
function openBestiary(){bestiaryOpen=true;bestiaryPage=0;drawBestiary()}
function bestiaryMatches(){const query=bestiarySearch.toLowerCase();return ENCOUNTERS.encounters.filter(d=>(!bestiaryDungeon||d.dungeon===bestiaryDungeon)&&(!bestiaryRole||d.role===bestiaryRole)&&(!query||(d.name+' '+d.enemy+' '+dungeonDefs[d.dungeon].name+' '+d.profile+' '+d.role).toLowerCase().includes(query)))}
function bestiaryFilter(key,value){if(key==='dungeon')bestiaryDungeon=value;else bestiaryRole=value;bestiaryPage=0;drawBestiary()}
function drawBestiary(){
 const focus=referenceFocus(),all=bestiaryMatches(),size=referenceSizes.bestiary,pages=Math.max(1,Math.ceil(all.length/size));bestiaryPage=Math.max(0,Math.min(bestiaryPage,pages-1));const active=[bestiaryDungeon,bestiaryRole].filter(Boolean).length;
 modal('Realm bestiary','Browse enemies by dungeon and role. Inspect for complete mechanics.',`
 <div class="reference-tools"><input id="bestiarySearch" placeholder="Search enemies, dungeons or profiles…" aria-label="Search encounters" value="${esc(bestiarySearch)}" oninput="filterBestiary(this.value)"><button id="referenceFilterToggle" class="reference-filter-toggle" aria-expanded="${referenceFiltersOpen}" aria-controls="referenceFilters" onclick="toggleReferenceFilters()">Filters${active?' · '+active:''}</button><button onclick="closeBestiary()">Close ✕</button></div>
 <div class="reference-filters" id="referenceFilters" data-open="${referenceFiltersOpen}"><label>Dungeon<select id="bestiaryDungeon" onchange="bestiaryFilter('dungeon',this.value)"><option value="">All dungeons</option>${Object.values(dungeonDefs).map(d=>`<option value="${d.id}" ${bestiaryDungeon===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label><label>Encounter role<select id="bestiaryRole" onchange="bestiaryFilter('role',this.value)"><option value="">All roles</option>${[...new Set(ENCOUNTERS.encounters.map(d=>d.role))].sort().map(role=>`<option value="${role}" ${bestiaryRole===role?'selected':''}>${esc(role)}</option>`).join('')}</select></label><button onclick="resetReferenceFilters('bestiary')">Reset</button><button class="reference-filter-done" onclick="toggleReferenceFilters()">Done</button></div>
 <div class="reference-summary"><span>${referenceSummary(all.length,bestiaryPage,size,'encounters')}</span><span id="referenceNotification" role="status">${s?.practice?'Sandbox · Try encounter to practise':'Stats scale to your run'}</span></div>
 <div class="reference-grid" data-reference="bestiary">${all.slice(bestiaryPage*size,(bestiaryPage+1)*size).map(d=>`<article class="reference-card" data-reference-id="${d.id}"><div class="reference-card-heading">${spriteMarkup(d.sprite,d.enemy,'itempixel')}<div><h3 title="${esc(d.enemy)}">${esc(d.enemy)}</h3><small>${esc(dungeonDefs[d.dungeon].name)} · ${d.role}</small></div></div><p class="reference-card-summary">${esc(encounterProfileDescription(d))}</p><div class="reference-card-meta">${dungeonDifficultyBadge(d.dungeon)}<span>${d.waves} wave${d.waves>1?'s':''}</span></div><div class="reference-card-actions"><button id="referenceInspect_${d.id}" onclick="inspectBestiaryEncounter('${d.id}')">Inspect</button>${s?.practice?`<button ${s.phase!=='prep'?'disabled':''} onclick="loadPracticeEncounter('${d.id}')">Try encounter</button>`:''}</div></article>`).join('')||`<div class="reference-empty"><h2>No matching encounters</h2><p>Try a shorter search or reset the filters.</p><button onclick="resetReferenceFilters('bestiary')">Reset search & filters</button></div>`}</div>
 ${referencePagination('bestiary',bestiaryPage,all.length,size)}`,'catalogue');referenceRestoreFocus(focus)
}
function inspectBestiaryEncounter(id){const d=encounterDefs[id];if(!d)return;referenceReturnFocus='referenceInspect_'+id;modal(d.enemy,`${esc(dungeonDefs[d.dungeon].name)} · ${d.role} · ${d.waves} wave${d.waves>1?'s':''}`,`<div>${spriteMarkup(d.sprite,d.enemy,'portalpixel')}${dungeonDifficultyBadge(d.dungeon)}${encounterDangerBadge(d)}</div><p>${esc(encounterProfileDescription(d))}</p>${d.role==='boss'?`<p class="synergy">Phase II: ${esc(dungeonSecondaryText(d))}</p>`:''}<p>Enemy stats scale with room depth and difficulty.</p><p><a href="${d.source}" target="_blank" rel="noopener">Wiki ↗</a></p><button onclick="returnReference('bestiary')">← Back to bestiary</button>`,'bestiaryinspect')}
function filterBestiary(value){bestiarySearch=value;bestiaryPage=0;drawBestiary();const e=$('bestiarySearch');e.focus();e.setSelectionRange(e.value.length,e.value.length)}
function closeBestiary(){bestiaryOpen=false;restorePhaseModal()}
function loadPracticeEncounter(id){if(!s.practice||s.phase!=='prep'||!encounterDefs[id])return;ROOMS[s.room]=scaledRoom(id,s.room+1);s.route=ROOMS;setEnemy();bestiaryOpen=false;closeModal(true);render();save()}
let expeditionRenderedState=null,expeditionRenderedRoom=null,expeditionRenderedPhase='';
function updateExpeditionUI(effectSummary=null){if(window.__TEST__||!s)return;const r=ROOMS[s.room],c=classes[s.classId],e=s.enemy;if(s.phase!=='fight'||expeditionRenderedState!==s||expeditionRenderedRoom!==r||expeditionRenderedPhase!==s.phase){expeditionRenderedState=s;expeditionRenderedRoom=r;expeditionRenderedPhase=s.phase;setStableHTML('dungeonDifficulty',dungeonDifficultyBadge(dungeonIdForRoom(r))+encounterDangerBadge(r));const begin=Math.floor(s.room/10)*10;setStableHTML('route',runMapMarkup());setTextValue($('routeCount'),'ACT '+(actIndex()+1));setTextValue($('runEyebrow'),`REALM DESCENT · ACT ${actIndex()+1} · ${difficulty().name.toUpperCase()}`);setTextValue($('roomtype'),`DEPTH ${s.room+1} · ${r.type.toUpperCase()}`);setTextValue($('roomtitle'),r.name);renderRoomArtwork(r);setStableHTML('encounterInfo',r.encounterId?`<div><b>${esc(ENCOUNTERS.profiles[r.profile].name)}</b> · ${esc(encounterProfileDescription(r))}</div>${r.type==='boss'?`<div class="synergy">Phase II: ${esc(dungeonSecondaryText(r))} The damage bonus resets each wave.</div>`:''}<div class="encounter-meta">${r.waves||1} wave${r.waves>1?'s':''} · ${r.gold} gold · ${r.risk?'Dangerous passage · ':''}${difficulty().name} · enemy strength scales with depth · Block: 60% HP cap, 10% decay/s · No consecutive dodges${r.type==='boss'?' · Boss: 15% piercing strikes, 30% affliction resistance':r.type==='elite'?' · Elite: 8% piercing strikes, 15% affliction resistance':''}</div>`:'<div>A moment to plan your next step in the descent.</div>');setTextValue($('runSummary'),`${s.eventBuffs&&Object.keys(s.eventBuffs).length?'Blessing ready · ':''}${s.kills} victories · ${s.bosses} bosses · ${s.boons.length} blessings`);}setTextValue($('estats'),e.max?`${Math.ceil(e.hp)} / ${e.max} HP${e.ward>0?' + '+Math.ceil(e.ward)+' ward':''} · ${e.damage} dmg / ${e.cd.toFixed(1)}s · wave ${e.wave} / ${r.waves||1}${e.phaseTwo?' · PHASE II':''}`:'A moment of respite');const extra=[];if(s.silence>0)extra.push('✕ silenced');if(s.venom>0)extra.push('☠ '+s.venom+' venom');if(s.slow>0)extra.push('❄ slowed');if(e.veil>0)extra.push('◇ enemy veil');if(s.phase==='fight'&&s.time>20)extra.push('healing '+Math.round(Math.max(.5,1-(s.time-20)*.02)*100)+'%');if(s.phase==='fight'&&s.time>=30)extra.push('ENRAGED');if(effectSummary!==null)setTextValue($('effects'),effectSummary+(extra.length?' · '+extra.join(' · '):''))}
function rebalanceSavedRoute(){migrateDungeonBalance();for(let i=s.room+1;i<ROOMS.length;i++)if(ROOMS[i].type==='rest'&&i%10===8)ROOMS[i]=decorateEventRoom({name:'',enemy:'A choice awaits',icon:'✦',hp:0,damage:0,cd:3,type:'event',depth:i+1,dungeonId:ROOMS[i].dungeonId});for(let i=s.room+1;i<ROOMS.length;i++)if(i%10===8&&ROOMS[i].type==='event')ROOMS[i]=decorateEventRoom({...ROOMS[i],eventId:'enchanter'});s.route=ROOMS;if(s.phase==='prep')setEnemy()}

function boot(){document.addEventListener('keydown',e=>{if(e.target.matches?.('input,select,textarea'))return;if(e.key.toLowerCase()==='r'&&!e.ctrlKey&&!e.metaKey&&!modalKind)rotateSelected();if(e.key==='Escape'){if(modalKind==='classconfirm')cancelClassStart();else if(bestiaryOpen)closeBestiary();else if(catalogueOpen)closeCatalogue();else if(modalKind)closeModal();else{selected=null;render()}}});try{const saved=JSON.parse(localStorage.getItem('realmpack-v4'));if(saved?.s?.version===4&&classes[saved.s.classId]&&Array.isArray(saved.s.route)&&saved.s.room>=0&&saved.s.room<saved.s.route.length&&[...saved.s.items,...saved.s.stash].every(i=>defs[i.type])){s=saved.s;ROOMS=s.route;uid=saved.uid;stock=saved.stock||[];reward=saved.reward||[];selectedDifficulty=s.difficulty;migrateDaggerItems();migrateConsumables();rebalanceSavedRoute();refreshEncounterArtwork();rebalanceGold();if(s.phase==='fight'){s.phase='prep';setEnemy()}render();log('Your expedition continues at depth '+(s.room+1)+'.');restorePhaseModal();return}const legacy=JSON.parse(localStorage.getItem('realmpack-v3'));if(legacy?.s&&classes[legacy.s.classId]&&[...legacy.s.items,...legacy.s.stash].every(i=>defs[i.type])){const old=legacy.s;freshRun(old.classId,old.practice);s.items=old.items;s.stash=old.stash;s.gold=old.gold;s.max=old.max;s.hp=Math.max(old.hp,Math.round(old.max*.5));uid=legacy.uid;migrateDaggerItems();migrateConsumables();save();render();toast('Your previous backpack has been carried into the expanded descent.');return}}catch{}freshRun('wizard');chooseClass()}

if(!window.__TEST__)boot();
